from __future__ import annotations

import json
import random
from datetime import datetime
from pathlib import Path

import numpy as np
import pandas as pd
import pytest
from sklearn.linear_model import LogisticRegression

from src.core.train import (
    ThresholdClassifier,
    _select_validation_patients_by_percent,
    run_classification_analysis_v2,
)
from src.core.stages.training import (
    TrainingSettings,
    build_training_models,
    generated_model_run_id,
    run_training,
    training_settings_from_config,
)
from src.core.v2_pipeline_run import create_run


def _run_with_feature_sets(tmp_path):
    tmp_path.mkdir(parents=True, exist_ok=True)
    clinical = tmp_path / "clinical.pkl"
    pd.DataFrame({"placeholder": [1]}).to_pickle(clinical)
    run = create_run(tmp_path / "extractions", clinical, run_name="training-test")
    run.extra["patient_splits"] = {
        "blind_test": {"patient_count": 0},
    }
    run.extra["feature_selection"] = {
        "selected_feature_count": 1,
        "selected_features": ["feature_one"],
    }
    frame = pd.DataFrame(
        {
            "file_write_time": ["t1", "t2"],
            "patient_id": ["p1", "p2"],
            "visit_number": [1, 1],
            "site_name": ["BC-Site1", "BC-Site1"],
            "channel_type": ["CLUSTER", "CLUSTER"],
            "study_group": ["NOT_LC", "LC"],
            "binary_study_group": [1, 2],
            "aggregated_reason": ["VALID", "VALID"],
            "feature_one": [0.1, 0.9],
        }
    )
    features_dir = run.run_path / "features"
    features_dir.mkdir()
    run.features_dir = features_dir
    frame.to_pickle(features_dir / "train_validation_set.pkl")
    frame.iloc[0:0].to_pickle(features_dir / "test_set.pkl")
    return run, frame
