def test_multi_trace_on_cluster_rows_is_rejected():
    """SW-589 G22: cluster rows can't be trained as traces.

    This used to be accepted (the flag overrode the clustering mode), so
    training treated each cluster row as a trace.
    """
    with pytest.raises(ValueError, match="allow_multi_trace must be false or null"):
        training_settings_from_config(
            {
                "pipeline": {
                    "stages": {
                        "clustering": {"enabled": True},
                        "training": {"enabled": True},
                    }
                },
                "training": {"allow_multi_trace": True},
            }
        )


def test_multi_trace_training_accepts_channels_and_patient_timestamp_collisions(tmp_path):
    rows = []
    for group, prefix in ((1, "control"), (2, "positive")):
        for patient_index in range(4):
            for channel_index in range(2):
                rows.append(
                    {
                        "file_write_time": "shared-timestamp",
                        "patient_id": f"{prefix}-{patient_index}",
                        "device_channel": f"ch{channel_index + 1}",
                        "visit_number": 1,
                        "site_name": "BC-Site1",
                        "channel_type": "SENSOR",
                        "study_group": "NOT_LC" if group == 1 else "LC",
                        "binary_study_group": group,
                        "aggregated_reason": "VALID",
                        "feature_one": group + patient_index / 10 + channel_index / 100,
                    }
                )
    frame = pd.DataFrame(rows)
    result = run_classification_analysis_v2(
        data=frame,
        test_data=frame.iloc[0:0].copy(),
        target_column="binary_study_group",
        models_binary={
            "logistic": ThresholdClassifier(LogisticRegression(), cv_folds=2)
        },
        permutations=1,
        val_size=50,
        allow_multi_trace=True,
        save_models=False,
        verbose=False,
        output_dir=str(tmp_path),
    )

    assert not result["patient_level_statistics"].empty
    assert result["patient_level_statistics"]["patient_id"].nunique() == 8


def _multi_trace_frame(n_patients: int = 6, n_channels: int = 3) -> pd.DataFrame:
    rows = []
    for group, prefix in ((1, "control"), (2, "case")):
        for patient_index in range(n_patients):
            for channel_index in range(n_channels):
                rows.append(
                    {
                        "file_write_time": f"{prefix}-{patient_index}-fwt",
                        "patient_id": f"{prefix}-{patient_index}",
                        "device_channel": f"ch{channel_index + 1}",
                        "sensor_type": "type_1",
                        "visit_number": 1,
                        "site_name": "BC-Site1",
                        "channel_type": "SENSOR",
                        "study_group": "F1" if group == 1 else "F3",
                        "binary_study_group": group,
                        "aggregated_reason": "VALID",
                        "feature_one": group
                        + patient_index / 10
                        + channel_index / 100,
                    }
                )
    return pd.DataFrame(rows)


def test_multi_trace_writes_trace_stats_and_votes_one_cluster_per_exam(tmp_path):
    frame = _multi_trace_frame()
    random.seed(3)
    result = run_classification_analysis_v2(
        data=frame,
        test_data=frame.iloc[0:0].copy(),
        target_column="binary_study_group",
        models_binary={
            "logistic": ThresholdClassifier(LogisticRegression(), cv_folds=2)
        },
        permutations=3,
        val_size=34,
        allow_multi_trace=True,
        save_models=False,
        verbose=False,
        output_dir=str(tmp_path),
    )

    traces = result["trace_level_statistics"]
    clusters = result["cluster_level_statistics"]
    assert set(traces.groupby("file_write_time")["device_channel"].nunique()) == {3}
    assert not traces.duplicated(["file_write_time", "device_channel", "set"]).any()
    assert not clusters.duplicated(["file_write_time", "set"]).any()
    assert "device_channel" not in clusters.columns
    assert set(clusters["n_traces"]) == {3}
    assert set(clusters["sensor_type"]) == {"type_1"}
    # A vote per permutation: never more predictions than permutations.

