STAGE_ORDER = (
    "preprocessing",
    "clustering",
    "features",
    "holdout",
    "training",
    "visualization",
    "model_reports",
)
STAGE_DEPENDENCIES = {
    if stage is not None and stage not in STAGE_ORDER:
        raise ValueError(
            f"{field_name} must be one of {', '.join(STAGE_ORDER)}"
        )


def _enabled(config: ResolvedPipelineConfig, stage: str) -> bool:
    return bool(config.data["pipeline"]["stages"][stage]["enabled"])


def _dependencies(stage: str, config: ResolvedPipelineConfig | None) -> tuple[str, ...]:
    if stage == "model_reports" and config is not None:
        return (resolve_model_report_source(config),)
    return STAGE_DEPENDENCIES[stage]


def _expand_dependencies(
    selected: set[str],
    config: ResolvedPipelineConfig | None = None,
) -> set[str]:
    expanded = set(selected)
    pending = list(selected)
    while pending:
        stage = pending.pop()
        for dependency in _dependencies(stage, config):
            if dependency not in expanded:
                expanded.add(dependency)
                pending.append(dependency)
    return expanded


def resolve_stage_plan(
    options: RunnerOptions,
    config: ResolvedPipelineConfig,
) -> list[str]:
    """Resolve enabled stages in dependency order."""
    _validate_stage(options.from_stage, "from_stage")
    _validate_stage(options.to_stage, "to_stage")
    requested = set(options.stages or ())
    unknown = requested - set(STAGE_ORDER)
    if unknown:
        raise ValueError(f"Unknown stages: {sorted(unknown)}")

    if requested:
        selected = _expand_dependencies(requested, config)
    else:
        selected = {
            stage
            for stage in STAGE_ORDER
            if _enabled(config, stage)
        }
        if any(stage in selected for stage in ("features", "visualization")):
            selected.add("clustering")
        selected = _expand_dependencies(selected, config)

    start = STAGE_ORDER.index(options.from_stage) if options.from_stage else 0
    end = (
        STAGE_ORDER.index(options.to_stage) + 1
        if options.to_stage
        else len(STAGE_ORDER)
    )
    if start >= end:
        raise ValueError("from_stage must not come after to_stage")
    return [
        stage
        for index, stage in enumerate(STAGE_ORDER)
        if start <= index < end and stage in selected
    ]


