def _stage_artifacts(run: PipelineRun, stage: str) -> list[Path]:
    return [
        run.run_path / relative_path
        for relative_path in REQUIRED_ARTIFACTS.get(stage, ())
    ]


def _dynamic_stage_complete(run: PipelineRun, stage: str) -> bool:
    if stage == "features":
        feature_runs = run.extra.get("feature_runs") or []
        if feature_runs:
            return any(
                entry.get("status") == "completed"
                for entry in feature_runs
            )
        features_dir = run.features_dir or (run.run_path / "features")
        return (features_dir / "train_validation_set.pkl").is_file()
    if stage == "training":
        model_runs = run.extra.get("model_runs") or []
        if model_runs:
            return all(
                entry.get("status") == "completed"
                for entry in model_runs
            )
        runs = run.extra.get("training_runs") or []
        return bool(
            runs
            and any(
                path.is_file()
                for path in (
                    run.run_path / runs[-1]["output_dir"]
                ).rglob("*")
            )
        )
    if stage == "holdout":
        return any(
            entry.get("status") == "completed"
            for entry in run.extra.get("holdout_runs") or []
        )
    if stage == "model_reports":
        path = (run.extra.get("artifacts") or {}).get("local", {}).get(
            "model_report_excel"
        )
        return bool(path and (run.run_path / path).is_file())
    return True


def should_skip_stage(
    run: PipelineRun,
    stage: str,
    *,
    resume: bool,
    force: bool,
) -> bool:
    if force or not resume:
        return False
    status = (run.extra.get("stages") or {}).get(stage, {}).get("status")
    if status not in {"completed", "skipped"}:
        return False
    artifacts = _stage_artifacts(run, stage)
    if any(not path.is_file() for path in artifacts):
        return False
    checksums = (run.extra.get("resume") or {}).get("artifact_checksums") or {}
    for path in artifacts:
        relative = str(path.relative_to(run.run_path))
        expected = checksums.get(relative)
        if expected and sha256_file(path) != expected:
            return False
    return _dynamic_stage_complete(run, stage)


def run_single_stage(
    stage: str,
    run: PipelineRun,
    config: ResolvedPipelineConfig,
    *,
    clinical_paths: Sequence[Path],
    prior_results: Mapping[str, Any],
    holdout_jobs: int = 1,
    features_extract_only: bool = False,
) -> Any:
    """Dispatch one stage while reusing in-memory results when available."""
    if stage == "preprocessing":
        return run_preprocessing(run, clinical_paths, config)
    if stage == "clustering":
        preprocessing = prior_results.get("preprocessing")
        return run_clustering(
            run,
            config,
            processed=getattr(preprocessing, "processed", None),
        )
    if stage == "features":
        clustering = prior_results.get("clustering")
        return run_features(
            run,
            config,
            clustered=getattr(clustering, "clustered", None),
            clustered_invalid=getattr(
                clustering,
                "clustered_invalid",
                None,
            ),
            processed=getattr(clustering, "processed", None),
            tracker=getattr(clustering, "tracker", None),
            extract_only=features_extract_only,
        )
    if stage == "holdout":
        return run_holdout(run, config, n_jobs=holdout_jobs)
    if stage == "training":
        return run_training(run, config)
    if stage == "visualization":
        clustering = prior_results.get("clustering")
        preprocessing = prior_results.get("preprocessing")
        return run_visualization(
            run,
            config,
            processed=getattr(preprocessing, "processed", None),
            clustered=getattr(clustering, "clustered", None),
            clustered_invalid=getattr(
                clustering,
                "clustered_invalid",
                None,
            ),
        )
    if stage == "model_reports":
        return run_model_reports(
            run,
            config,
            training_result=prior_results.get("training"),
            holdout_result=prior_results.get("holdout"),
        )
    raise ValueError(f"Unknown pipeline stage: {stage}")


def _record_resume_artifacts(
    run: PipelineRun,
    completed_stages: Sequence[str],
) -> None:
    checksums = dict(
        (run.extra.get("resume") or {}).get("artifact_checksums") or {}
    )
    for stage in completed_stages:
        for path in _stage_artifacts(run, stage):
            if path.is_file():
                relative = str(path.relative_to(run.run_path))
                checksum = sha256_file(path)
                checksums[relative] = checksum
                record_artifact(
                    run,
                    relative.replace("/", "_"),
                    local_path=path,
                    checksum=checksum,
                    persist=False,
                )
    update_resume_state(
        run,
        requested_from_stage=None,
        completed_stages=completed_stages,
        artifact_checksums=checksums,
    )


def run_pipeline(options: RunnerOptions) -> PipelineExecutionResult:
    """Execute an ordered, resumable Pipeline V2 stage plan."""
    config, run, clinical_paths = prepare_run_context(options)
    plan = resolve_stage_plan(options, config)
    if options.dry_run:
        return PipelineExecutionResult(
            config=config,
            run=run,
            planned_stages=tuple(plan),
            stages=(),
        )
    if run is None:
        raise RuntimeError("Pipeline run was not prepared")

    executed: list[StageExecutionResult] = []
    prior_results: dict[str, Any] = {}
    completed = list(
        (run.extra.get("resume") or {}).get("completed_stages") or []
    )
    update_resume_state(
        run,
        requested_from_stage=options.from_stage or (plan[0] if plan else None),
    )
    for stage in plan:
        if should_skip_stage(
            run,
            stage,
            resume=options.resume,
            force=options.force,
        ):
            executed.append(StageExecutionResult(stage, "skipped"))
            if stage not in completed:
                completed.append(stage)
            continue
        result = run_single_stage(
            stage,
            run,
            config,
            clinical_paths=clinical_paths,
            prior_results=prior_results,
            holdout_jobs=options.holdout_jobs,
            features_extract_only=features_extract_only_for_plan(plan),
        )
        prior_results[stage] = result
        status = "skipped" if getattr(result, "skipped", False) else "completed"
        executed.append(StageExecutionResult(stage, status, result))
        if status == "completed" and stage not in completed:
            completed.append(stage)
        _record_resume_artifacts(run, completed)
    return PipelineExecutionResult(
        config=config,
        run=run,
        planned_stages=tuple(plan),
        stages=tuple(executed),
    )

